            c.querySelectorAll('.py-tc').forEach(function(t){t.classList.remove('on')});
            el.classList.add('on');
            document.getElementById(id).classList.add('on');
        }

        /* 三模式循环切换：暗色 → 魔法 → 亮色 → 暗色 */
        var pyModeState = 0; /* 0=暗色 1=魔法 2=亮色 */

        function pyMode() {
            var c = document.getElementById('pyC');
            var btn = document.getElementById('mBtn');
            var icon = document.getElementById('pyIcon');
            var burst = document.getElementById('pyBurst');
            var dotDk = document.getElementById('dot-dk');
            var dotMg = document.getElementById('dot-mg');
            var dotLt = document.getElementById('dot-lt');

            /* 爆发特效 */
            burst.classList.remove('go');
            void burst.offsetWidth;
            burst.classList.add('go');

            setTimeout(function(){
                /* 清除所有模式class */
                c.classList.remove('magic', 'light');
                dotDk.classList.remove('now');
                dotMg.classList.remove('now');
                dotLt.classList.remove('now');

                pyModeState = (pyModeState + 1) % 3;

                if (pyModeState === 1) {
                    /* 切到魔法 */
                    c.classList.add('magic');
                    btn.innerHTML = '☼ 亮色模式';
                    icon.textContent = '🔮';
                    dotMg.classList.add('now');
                } else if (pyModeState === 2) {
                    /* 切到亮色 */
                    c.classList.add('light');
                    btn.innerHTML = '⛓ 暗色模式';
                    icon.textContent = '🩹';
                    dotLt.classList.add('now');
                } else {
                    /* 切回暗色 */
                    btn.innerHTML = '✦ 魔法模式';
                    icon.textContent = '🔒';
                    dotDk.classList.add('now');
                }
            }, 280);

            setTimeout(function(){
                burst.classList.remove('go');
            }, 900);
        }
